#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const sessionsDir = path.join(__dirname, '.sessions');
const worktreesDir = path.join(__dirname, '../.city-worktrees');

const args = process.argv.slice(2);
const isCleanMode = args.includes('--clean');

const sessions = fs.readdirSync(sessionsDir).map(file => {
  const content = fs.readFileSync(path.join(sessionsDir, file), 'utf8');
  return JSON.parse(content);
});

const completedSessions = sessions.filter(session =>
  session.status === 'completed' || session.turns >= session.max_turns
);

completedSessions.forEach(session => {
  const worktreePath = path.join(worktreesDir, session.id);
  if (fs.existsSync(worktreePath)) {
    const stats = fs.statSync(worktreePath);
    const age = Math.floor((Date.now() - stats.mtimeMs) / (1000 * 60 * 60 * 24));

    console.log(`Session: ${session.id} | Status: ${session.status} | Age: ${age} days`);

    if (isCleanMode) {
      try {
        execSync("git worktree remove --force " + JSON.stringify(worktreePath), { stdio: "inherit" });
        console.log(`Removed worktree for session ${session.id}`);
      } catch (error) {
        console.error(`Error removing worktree for session ${session.id}:`, error.message);
      }
    }
  }
});

